values ('cumpleanos', 'Cumpleaños', 'Cumpleaños', '¡Celebrá su día de manera especial con un detalle inolvidable!',
        'draft', 2, '{"title":"Boxie de","highlight":"Cumpleaños","subtitle":"¡Hacé que su día sea inolvidable a la distancia!","cardDescription":"¡Celebra su día de manera especial con un detalle inolvidable!","cardColor":"#73CFEE","cardTone":"dark","images":["/themes/cumpleanos.jpg","https://images.unsplash.com/photo-1558636508-e0db3814bd1d?q=80&w=800&auto=format&fit=crop"],"features":["Portada con su nombre y la torta con las velas de su edad.","Tu carta en un sobre que se abre, escrita a mano.","Sus mejores momentos en polaroids, año por año.","Trivia, tragamonedas, piñata y vales para canjear.","Regalo sorpresa al final, si querés sumar uno."],"guide":{"emoji":"🎂","title":"Para Festejar","text":"¡La fiesta digital! Perfecta para saludos grupales, videos de amigos y recuerdos de cumpleaños anteriores."}}'::jsonb, '{"palette":{"primary":"#F44E63","ink":"#1C2A5A","accent":"#FFD35C"},"slides":[{"key":"intro","kind":"intro.brand","props":{"tagline":"Una experiencia digital para vos.","hint":"Deslizá para comenzar"},"frame":{"background":"none","particles":"none","fullScreen":true,"confetti":false,"chrome":"light"}},{"key":"portada","kind":"cover.cake","props":{"kicker":"Hoy es un día especial para...","greeting":"¡Feliz cumple! 🎉","cta":"🎂 Tocá para soplar las velitas","blown":"¡Deseo pedido! Deslizá para seguir","senderPrefix":"DE PARTE DE:"},"frame":{"background":"none","particles":"none","fullScreen":true,"confetti":false,"chrome":"light"}},{"key":"edicion","kind":"cover.age","props":{"kicker":"EDICIÓN CUMPLE","caption":"vueltas al sol ☀️","chip1":"🎉 Hoy se festeja","chip2":"👑 {{rol}} del año","wishLabel":"UN DESEO PARA EMPEZAR","defaultWish":"Que este año te traiga todo lo que te merecés.","cta":"Empezar el festejo →"},"frame":{"background":"none","particles":"none","fullScreen":true,"confetti":false,"chrome":"light"}},{"key":"tarjeta","kind":"story.card","props":{"kicker":"PARA VOS","title":"Tu tarjeta de cumple","subtitle":"de {{de}}","envelopeLine":"¡Feliz cu